390	/** Exported so lib/marketing/gameLocationLandings.ts can reuse the same "and"-joined list phrasing. */
391	export function listPhrase(items: string[]): string {
392	  if (items.length <= 1) return items.join("");
393	  return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
394	}
