export type GameLocationDef = {
  slug: string;
  /** Display name, e.g. "South Korea", "Southeast Asia". */
  name: string;
  /** Adjective for the audience, e.g. "Korean". */
  audience: string;
  /** Longer regional phrase for prose. */
  regionLong: string;
  /** Nearby cities/countries for prose variety. */
  nearby: string[];
  /** One factual, geography-grounded sentence used in the intro prose. */
  hub: string;
  /** Same three-value honesty flag as LocationDef in locationLandings.ts. */
  presence: "datacenter" | "network" | "market";
  /** ISO2 code for flagEmoji(), or "" to use the globe fallback below. */
  flag: string;
  /** Present only when `flag` is a deliberate stand-in, not this location's own country — explains the choice (owner asked every location show a real flag; an aggregate has none of its own). */
  flagNote?: string;
};

