591	/* ------------------------------------------------------------------ */
592	/* GameLandingCombined adapter (2026-09-19) — renders game×location      */
593	/* combos through the SAME flagship template as the ~40 hand-built      */
594	/* per-game pages, instead of the generic UseCaseLanding/PricingGrid    */
595	/* path above. See the file doc at the top: `buildGameLocationLanding`  */
596	/* above still exists (its FAQ/related/JSON-LD content is reused below, */
597	/* just not its own `useCaseContent` hero/intro/why/steps rendering).   */
598	/* ------------------------------------------------------------------ */
599

599	
600	/** This location's nearest REAL Nxeon region key (sgp1/fsn1), or undefined
601	 * when neither is honestly closer (the "market" locations — US/NA/Canada) —
602	 * passed to `deployHref({ region })` so the wizard can pre-select it without
603	 * ever implying a region that isn't genuinely the better round-trip. Derived
604	 * from the exact same geography-grounded `presence` reasoning already
605	 * documented on `GAME_LOCATIONS` above (Singapore/SEA/network-Asia → sgp1,
606	 * Germany/Europe/network-Europe → fsn1), not a new judgment call. */
607	function nearestRealRegion(loc: GameLocationDef): "sgp1" | "fsn1" | undefined {
608	  const sgSide = new Set(["singapore", "southeast-asia", "south-korea", "japan", "malaysia", "indonesia", "india", "australia"]);
609	  const deSide = new Set(["germany", "europe", "united-kingdom", "netherlands"]);
610	  if (sgSide.has(loc.slug)) return "sgp1";
611	  if (deSide.has(loc.slug)) return "fsn1";
612	  return undefined; // united-states, north-america, canada — genuinely no honest answer
613	}
614	
615	/** Hero trust-strip chip text, replacing "Singapore · low latency" — honest per `presence`. */
616	function trustStripLabel(loc: GameLocationDef): string {
617	  if (loc.presence === "datacenter") return `${loc.name} · real datacenter`;
618	  if (loc.presence === "network") return `${loc.name} · low-latency network`;
619	  return `${loc.name} audience · served from SG/DE`;
620	}
621	
622	/** HUD deploy-beat region tag, replacing the hardcoded "Singapore · sgp1". */
623	function regionTagLabel(loc: GameLocationDef): string {
624	  const region = nearestRealRegion(loc);
625	  if (region) return `${REGION_LABELS_LOCAL[region]} · ${region}`;
626	  return "Singapore or Germany";
627	}
628	const REGION_LABELS_LOCAL: Record<"sgp1" | "fsn1", string> = { sgp1: "Singapore", fsn1: "Falkenstein, DE" };
629	
630	/** Short, honest, position-derived tier label — real GamePlan rows don't carry
631	 * a flavor-name like PREVIEW_GAMES' "Starter wipe"/"Community"/"Big wipe", so
632	 * this reads off the ladder position instead of inventing per-tier prose. */
633	function tierLabel(idx: number, n: number): string {
634	  if (n <= 1) return "Standard";
635	  if (idx === 0) return "Starter";
636	  if (idx === n - 1) return "Pro";
637	  return "Standard";
638	}
639	
640	/** Real-data-only feature list for a game plan card — mirrors PricingGrid.tsx's
641	 * own `planFeatures(p, "game")` (slots headline, then real spec, FTP, DDoS);
642	 * duplicated in miniature here rather than importing a private helper from a
643	 * "use client" component into this server-safe data module. */
644	function gamePlanFeatures(p: PlanCard): string[] {
645	  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
646	  return [
647	    ...(p.slots ? [`${p.slots} player slots`] : []),
648	    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
649	    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
650	    `${p.diskGB} GB ${disk}`,
651	    "Full file access (FTP)",
652	    "Free DDoS protection",
653	  ];
654	}
655	
656	/**
657	 * Real `GamePlan`/basePlan rows (`cards`, already fetched by the route for the
658	 * pricing grid) mapped into `PreviewPlan[]` — the shape GameLandingCombined's
659	 * plan cards and configurator actually read. Every number is real: price and
660	 * intro price from `priceCents`/`introPriceCents` (via the same
661	 * `planIntroMonthlyCents` helper the rest of the site's intro-pricing display
662	 * uses), RAM/CPU/disk/slots from the row itself. Nothing here is fabricated —
663	 * `blurb`/`tier`/`features` are derived text, not invented numbers.
664	 */
665	function buildRealPreviewPlans(gameName: string, cards: PlanCard[]): PreviewPlan[] {
666	  const popularIdx = cards.length ? Math.floor((cards.length - 1) / 2) : -1;
667	  return cards.map((p, i) => {
668	    // `PlanCard` exposes the intro rate as `introMonthlyCents` (its own display
669	    // field name — see PricingGrid.tsx), not the raw Prisma `introPriceCents`
670	    // column `planIntroMonthlyCents` reads by default, so check it explicitly
671	    // first, exactly the way PricingGrid.tsx's own price block does.
672	    const introCents = p.introMonthlyCents ?? planIntroMonthlyCents(p);
673	    const hasIntro = introCents != null;
674	    return {
675	      id: p.id,
676	      tier: tierLabel(i, cards.length),
677	      ram: `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB`,
678	      price: money(hasIntro ? introCents! : p.priceCents),
679	      renewalPrice: hasIntro ? money(p.priceCents) : undefined,
680	      meta: p.slots ? `${p.slots} slots` : `${p.cpuCores} vCPU · ${p.diskGB} GB NVMe`,
681	      slots: p.slots ?? undefined,
682	      blurb: p.slots
683	        ? `A dedicated ${gameName} server sized for up to ${p.slots} concurrent players.`
684	        : `A dedicated ${gameName} server with ${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM and ${p.diskGB} GB NVMe.`,
685	      popular: i === popularIdx,
686	      features: gamePlanFeatures(p),
687	    };
688	  });
689	}
