/* ── region card ──────────────────────────────────────────────────────── */
/* The sandbox card carried a site count and a latency figure per region. The
   platform records neither, so rather than print invented numbers the card shows
   what is true: where it is, and which continent it sits on. */
export function RegionCard({ r, on, onClick }: {
  r: { key: string; name: string; area: string; flag: string; ms?: number; rec?: boolean };
  on: boolean; onClick: () => void;
}) {
  return (
    <Pick on={on} onClick={onClick} className="card-glass flex items-center gap-3 p-3"
          style={{ "--tone": "#3fd0ff" } as React.CSSProperties}>
      <Flag code={r.flag} size={26} />
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="flex items-center gap-2">
          <span className="trunc text-[13.5px] font-bold text-white">{r.name}</span>
          {r.rec && (
            <span className="flex-none rounded-full border border-[rgba(72,148,255,0.4)] bg-[rgba(10,40,96,0.6)]
                             px-2 py-[1px] text-[9.5px] font-bold text-[#8dbde8]">
              Recommended
            </span>
          )}
        </span>
        <span className="trunc text-[11.5px] text-tx-faint">{r.area}</span>
      </span>
      {/* "~" because this is the region's nominal round-trip, not a measurement
          of THIS visitor's connection — nothing probes that. */}
      {r.ms !== undefined && (
        <span className="flex flex-none items-center gap-1.5 text-[11.5px] font-semibold text-mint">
          <Bars ms={r.ms} />~{r.ms} ms
        </span>
      )}
    </Pick>
  );
}

/** Three bars, filled by how good the latency is — a glanceable read that a
    bare number does not give. */
function Bars({ ms }: { ms: number }) {
  const lit = ms < 40 ? 3 : ms < 70 ? 2 : 1;
  return (
    <span className="flex items-end gap-[2px]" aria-hidden>
      {[5, 8, 11].map((h, i) => (
        <span key={h} style={{ height: h }}
              className={"w-[3px] rounded-[1px] " + (i < lit ? "bg-mint" : "bg-[rgba(120,160,210,0.28)]")} />
      ))}
    </span>
  );
}

